/** @param {NS} ns */
export async function main(ns) {
  // Minimal RAM footprint - only use cheap calls
  const visited = new Set();
  const queue = ['home'];
  const servers = [];

  // Scan network
  while (queue.length > 0) {
    const host = queue.shift();
    if (visited.has(host)) continue;
    visited.add(host);
    servers.push(host);
    const neighbors = ns.scan(host);
    for (const n of neighbors) {
      if (!visited.has(n)) queue.push(n);
    }
  }

  ns.tprint('Servers found: ' + servers.length);

  // Try to root each server
  for (const s of servers) {
    if (s === 'home') continue;
    try { ns.brutessh(s); } catch(e) {}
    try { ns.ftpcrack(s); } catch(e) {}
    try { ns.relaysmtp(s); } catch(e) {}
    try { ns.httpworm(s); } catch(e) {}
    try { ns.sqlinject(s); } catch(e) {}
    try { ns.nuke(s); } catch(e) {}
  }

  // Pick best target
  const myLevel = ns.getHackingLevel();
  let best = null, bestScore = -1;
  for (const s of servers) {
    if (s === 'home') continue;
    if (!ns.hasRootAccess(s)) continue;
    const req = ns.getServerRequiredHackingLevel(s);
    if (req > myLevel) continue;
    const maxMoney = ns.getServerMaxMoney(s);
    const minSec = ns.getServerMinSecurityLevel(s);
    if (maxMoney <= 0) continue;
    const score = maxMoney / minSec;
    if (score > bestScore) { bestScore = score; best = s; }
  }

  if (!best) { ns.tprint('No valid target found'); return; }
  ns.tprint('Target: ' + best + ' score=' + bestScore.toFixed(0));

  // Main loop
  while (true) {
    const sec = ns.getServerSecurityLevel(best);
    const minSec = ns.getServerMinSecurityLevel(best);
    const money = ns.getServerMoneyAvailable(best);
    const maxMoney = ns.getServerMaxMoney(best);

    if (sec > minSec + 5) {
      await ns.weaken(best);
    } else if (money < maxMoney * 0.75) {
      await ns.grow(best);
    } else {
      await ns.hack(best);
    }
  }
}

